"use strict";
const fs=require('fs'),path=require('path'),cp=require('child_process'),assert=require('assert/strict');
const {memory}=require('../tests/espn-synthetic-session.test');
(async()=>{const root=path.resolve(__dirname,'..'),out=root+'/.sage-acceptance';const {zipFunctions}=await import(process.env.SAGE_ZISI_MODULE);const dest=fs.mkdtempSync('/tmp/sage-synthetic-bundle-');const result=await zipFunctions(out+'/functions',dest,{basePath:root+'/acceptance',config:{'*':{nodeBundler:'esbuild',nodeVersion:'24',includedFiles:['../.sage-acceptance/lib/**']}}});assert.equal(result.length,3);const extract=dest+'/extracted';cp.execFileSync('unzip',['-q',dest+'/chatgpt-mcp.zip','-d',extract]);const entry=cp.execFileSync('unzip',['-Z1',dest+'/chatgpt-mcp.zip'],{encoding:'utf8'}).split('\n').find(n=>n.endsWith('/functions/chatgpt-mcp.js'));const probe=path.join(extract,entry)+'.probe.cjs';fs.writeFileSync(probe,fs.readFileSync(path.join(extract,entry),'utf8')+'\nexports.probe={core:require_synthetic_session(),snapshot:require_league_snapshot(),runner:require_espn_preservation_assertions()};\n');const {core,snapshot,runner}=require(probe).probe;const data=memory();const s=core.create({store:()=>data,expected:require(out+'/lib/acceptance/synthetic-expected.json'),canonical:snapshot.acceptanceCanonical,assertions:c=>runner.run(c)});const start=await s.begin();assert.equal(start.ok,true);for(const [team,input]of Object.entries(require(out+'/lib/acceptance/synthetic-expected.json')))assert.equal((await s.upload(start.token,team,input)).ok,true);const good=await s.inspect();assert.equal(Object.values(good.assertions).filter(x=>x==='PASS').length,7);const record=data.data.get(core.KEY);record.data.cases['synthetic-a'].snapshot.roster[0].lineupSlotId=5;const broken=await s.inspect();assert.equal(broken.assertions.player_slot_associations,'FAIL');assert.equal(Object.values(broken.assertions).filter(x=>x==='PASS').length,6);await s.cleanup();assert.equal((await core.create({store:()=>data,expected:{},canonical:()=>{},assertions:()=>{}}).verifyAbsent()).absent,true);console.log(JSON.stringify({bundledRuntime:'PASS',assertions:good.assertions,brokenFixture:'one expected FAIL',cleanup:'PASS',functions:result.map(x=>x.name)}));})().catch(e=>{console.error(e);process.exitCode=1;});
